import json, textwrap
obj=json.load(open('/app/benchmark/source_data.json'))
services={s['id']:s for s in obj['microservices']['data']}
topics={t['topic_name']:t for t in obj['kafka_topics']['data']}
flows=obj['event_flows']['data']
retry={r['service_id']:r for r in obj['retry_policies']['data']}

# Build helpers
producer_edges=[f for f in flows if f['flow_type']=='produce']
consume_edges=[f for f in flows if f['flow_type']=='consume']
dlq_edges=[f for f in flows if f['flow_type']=='dlq-produce']
schema_edges=[f for f in flows if f['flow_type']=='schema-lookup']

print('producer_edges',len(producer_edges))
print('consume_edges',len(consume_edges))
print('dlq_edges',len(dlq_edges))
print('schema_edges',len(schema_edges))

# Identify producers per topic and consumers per topic
prod_by_topic={}
cons_by_topic={}
for f in producer_edges:
    prod_by_topic.setdefault(f['target'],[]).append(f['source'])
for f in consume_edges:
    cons_by_topic.setdefault(f['source'],[]).append(f['target'])

print('\nTopic hubs:')
for tn in topics:
    print(tn,'prod',prod_by_topic.get(tn,[]),'cons',cons_by_topic.get(tn,[]))

